"use client";

/**
 * Presentational preview. Renders whatever CvData it receives —
 * the live draft in edit mode, so changes appear while typing.
 * The visual design (layout, classes) is unchanged from the original CV page.
 */

import type { CvData } from "@/lib/cv/types";

function SectionTitle({ children }: { children: React.ReactNode }) {
  return (
    <h2 className="mb-3 border-b-2 border-slate-800 pb-1 text-sm font-bold uppercase tracking-widest text-slate-800">
      {children}
    </h2>
  );
}

/** Strip protocol for display, e.g. "https://github.com/x" -> "github.com/x". */
function displayUrl(url: string): string {
  return url.replace(/^https?:\/\//, "").replace(/\/$/, "");
}

export function CvPreview({ cv }: { cv: CvData }) {
  const links = [
    cv.contact.links.linkedin,
    cv.contact.links.github,
    cv.contact.links.portfolio,
  ]
    .filter(Boolean)
    .map(displayUrl);

  return (
    <main className="cv-page mx-auto w-full max-w-[210mm] bg-white p-12 shadow-lg print:max-w-none print:p-0 print:shadow-none">
      {/* Header */}
      <header className="mb-8 flex items-start justify-between gap-6 border-b-4 border-slate-800 pb-6">
        <div className="flex items-start gap-5">
          {cv.photo && (
            // eslint-disable-next-line @next/next/no-img-element -- local data URL
            <img
              src={cv.photo}
              alt={`Photo de ${cv.name}`}
              className="h-24 w-24 shrink-0 rounded-full border-2 border-slate-800 object-cover"
            />
          )}
          <div>
            <h1 className="text-4xl font-extrabold tracking-tight text-slate-900">
              {cv.name || "Votre nom"}
            </h1>
            <p className="mt-1 text-lg font-medium text-slate-600">
              {cv.title}
            </p>
          </div>
        </div>
        <div className="text-right text-sm leading-relaxed text-slate-600">
          {cv.contact.email && <p>{cv.contact.email}</p>}
          {cv.contact.phone && <p>{cv.contact.phone}</p>}
          {cv.contact.address && <p>{cv.contact.address}</p>}
          {links.map((link) => (
            <p key={link}>{link}</p>
          ))}
        </div>
      </header>

      {/* Summary */}
      {cv.summary.trim() !== "" && (
        <section className="mb-8">
          <SectionTitle>Profile</SectionTitle>
          <p className="whitespace-pre-line text-sm leading-relaxed text-slate-700">
            {cv.summary}
          </p>
        </section>
      )}

      {/* Experience */}
      {cv.experiences.length > 0 && (
        <section className="mb-8">
          <SectionTitle>Professional Experience</SectionTitle>
          <div className="space-y-6">
            {cv.experiences.map((exp) => (
              <article key={exp.id}>
                <div className="flex flex-wrap items-baseline justify-between gap-x-4">
                  <h3 className="text-base font-bold text-slate-900">
                    {exp.title}
                    {(exp.title || exp.company) && (
                      <span className="font-medium text-slate-600">
                        {" · "}
                        {exp.company}
                      </span>
                    )}
                  </h3>
                  <span className="text-xs font-medium uppercase tracking-wide text-slate-500">
                    {[exp.period, exp.location].filter(Boolean).join(" · ")}
                  </span>
                </div>
                {exp.bullets.filter(Boolean).length > 0 && (
                  <ul className="mt-2 list-disc space-y-1 pl-5 text-sm leading-relaxed text-slate-700">
                    {exp.bullets.filter(Boolean).map((b, i) => (
                      <li key={`${exp.id}-${i}`}>{b}</li>
                    ))}
                  </ul>
                )}
              </article>
            ))}
          </div>
        </section>
      )}

      {/* Education */}
      {cv.education.length > 0 && (
        <section className="mb-8">
          <SectionTitle>Education</SectionTitle>
          <div className="space-y-4">
            {cv.education.map((edu) => (
              <article key={edu.id}>
                <div className="flex flex-wrap items-baseline justify-between gap-x-4">
                  <h3 className="text-base font-bold text-slate-900">
                    {edu.degree}
                  </h3>
                  <span className="text-xs font-medium uppercase tracking-wide text-slate-500">
                    {edu.period}
                  </span>
                </div>
                {edu.school && (
                  <p className="text-sm text-slate-600">{edu.school}</p>
                )}
                {edu.details && (
                  <p className="mt-1 text-sm text-slate-700">{edu.details}</p>
                )}
              </article>
            ))}
          </div>
        </section>
      )}

      {/* Skills */}
      {cv.skills.length > 0 && (
        <section className="mb-8">
          <SectionTitle>Skills</SectionTitle>
          <dl className="grid grid-cols-2 gap-x-8 gap-y-3 text-sm">
            {cv.skills
              .filter((s) => s.category || s.items.some(Boolean))
              .map((s) => (
                <div key={s.id}>
                  <dt className="font-semibold text-slate-900">{s.category}</dt>
                  <dd className="mt-0.5 text-slate-700">
                    {s.items.filter(Boolean).join(", ")}
                  </dd>
                </div>
              ))}
          </dl>
        </section>
      )}

      {/* Languages */}
      {cv.languages.length > 0 && (
        <section className="mb-8">
          <SectionTitle>Languages</SectionTitle>
          <ul className="flex flex-wrap gap-x-8 gap-y-1 text-sm text-slate-700">
            {cv.languages.map((l) => (
              <li key={l.id}>
                <span className="font-semibold text-slate-900">
                  {l.language}
                </span>
                {l.level && <> — {l.level}</>}
              </li>
            ))}
          </ul>
        </section>
      )}

      {/* Certifications */}
      {cv.certifications.length > 0 && (
        <section>
          <SectionTitle>Certifications</SectionTitle>
          <ul className="space-y-2 text-sm text-slate-700">
            {cv.certifications.map((cert) => (
              <li key={cert.id} className="flex flex-wrap justify-between gap-x-4">
                <span>
                  <span className="font-semibold text-slate-900">
                    {cert.name}
                  </span>
                  {cert.issuer && <> — {cert.issuer}</>}
                </span>
                {cert.year && (
                  <span className="text-xs font-medium uppercase tracking-wide text-slate-500">
                    {cert.year}
                  </span>
                )}
              </li>
            ))}
          </ul>
        </section>
      )}
    </main>
  );
}
